import React from 'react';
import { 
  Container, 
  Typography, 
  Paper, 
  Grid, 
  Box, 
  List, 
  ListItem, 
  ListItemIcon, 
  ListItemText 
} from '@mui/material';
import { 
  Computer, 
  Speed, 
  Security, 
  CloudQueue 
} from '@mui/icons-material';

const Home = () => {
  return (
    <Box sx={{ 
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      py: 0
    }}>
      <Container maxWidth="lg" sx={{ pt: 6, pb: 8 }}>
        {/* Hero Section */}
        <Box sx={{ 
          textAlign: 'center', 
          mb: 8,
          color: 'white'
        }}>
          <Typography 
            variant="h2" 
            sx={{ 
              fontWeight: 300,
              mb: 2,
              fontSize: { xs: '2.5rem', md: '3.5rem' }
            }}
          >
            Clúster Raspberry Pi
          </Typography>
          <Typography 
            variant="h5" 
            sx={{ 
              fontWeight: 300,
              opacity: 0.9,
              mb: 4
            }}
          >
            Kubernetes para el futuro
          </Typography>
        </Box>

        {/* Main Image */}
        <Box
          sx={{
            mb: 8,
            display: 'flex',
            justifyContent: 'center'
          }}
        >
          <Box
            component="img"
            src="cluster-background.png" 
            alt="Imagen del Clúster Raspberry Pi"
            sx={{
              width: '100%',
              maxWidth: 800,
              height: 300,
              objectFit: 'cover',
              borderRadius: 3,
              boxShadow: '0 20px 40px rgba(0,0,0,0.3)',
            }}
          />
        </Box>

        {/* Content Grid */}
        <Grid container spacing={6}>
          {/* Main Content */}
          <Grid item xs={12} md={8}>
            <Paper 
              elevation={0}
              sx={{ 
                p: 4, 
                mb: 4,
                background: 'rgba(255,255,255,0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: 3,
                border: '1px solid rgba(255,255,255,0.2)'
              }}
            >
              <Typography 
                variant="h4" 
                sx={{ 
                  fontWeight: 300,
                  mb: 3,
                  color: '#2c3e50'
                }}
              >
                ¿Qué es un Clúster de Raspberry Pi?
              </Typography>
              <Typography 
                variant="body1" 
                sx={{ 
                  lineHeight: 1.8,
                  color: '#34495e',
                  mb: 4
                }}
              >
                Un Clúster de Raspberry Pi es un conjunto de computadoras Raspberry Pi 
                conectadas entre sí que trabajan de manera coordinada para ejecutar 
                aplicaciones distribuidas. Cada Raspberry Pi actúa como un nodo en el 
                Clúster, proporcionando recursos de CPU, memoria y almacenamiento.
              </Typography>

              <Typography 
                variant="h4" 
                sx={{ 
                  fontWeight: 300,
                  mb: 3,
                  color: '#2c3e50'
                }}
              >
                Kubernetes en Raspberry Pi
              </Typography>
              <Typography 
                variant="body1" 
                sx={{ 
                  lineHeight: 1.8,
                  color: '#34495e'
                }}
              >
                Kubernetes es una plataforma de orquestación de contenedores que nos 
                permite gestionar y escalar aplicaciones de manera automática. En nuestro 
                Clúster de Raspberry Pi, Kubernetes coordina la ejecución de contenedores 
                Docker a través de múltiples nodos, proporcionando alta disponibilidad 
                y balanceamiento de carga.
              </Typography>
            </Paper>
          </Grid>

          {/* Benefits Sidebar */}
          <Grid item xs={12} md={4}>
            <Paper 
              elevation={0}
              sx={{ 
                p: 4,
                background: 'rgba(255,255,255,0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: 3,
                border: '1px solid rgba(255,255,255,0.2)'
              }}
            >
              <Typography 
                variant="h5" 
                sx={{ 
                  fontWeight: 300,
                  mb: 3,
                  color: '#2c3e50'
                }}
              >
                Beneficios del Clúster
              </Typography>
              <List sx={{ p: 0 }}>
                {[
                  { icon: <Speed />, title: "Alto Rendimiento", subtitle: "Procesamiento distribuido" },
                  { icon: <Security />, title: "Alta Disponibilidad", subtitle: "Tolerancia a fallos" },
                  { icon: <CloudQueue />, title: "Escalabilidad", subtitle: "Fácil adición de nodos" },
                  { icon: <Computer />, title: "Costo Efectivo", subtitle: "Hardware económico" }
                ].map((item, index) => (
                  <ListItem key={index} sx={{ px: 0, py: 2 }}>
                    <ListItemIcon>
                      <Box
                        sx={{
                          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                          borderRadius: '50%',
                          p: 1,
                          color: 'white'
                        }}
                      >
                        {item.icon}
                      </Box>
                    </ListItemIcon>
                    <ListItemText 
                      primary={
                        <Typography sx={{ fontWeight: 500, color: '#2c3e50' }}>
                          {item.title}
                        </Typography>
                      }
                      secondary={
                        <Typography sx={{ color: '#7f8c8d', fontSize: '0.875rem' }}>
                          {item.subtitle}
                        </Typography>
                      }
                    />
                  </ListItem>
                ))}
              </List>
            </Paper>
          </Grid>
        </Grid>

        {/* Use Cases Section */}
        <Paper 
          elevation={0}
          sx={{ 
            p: 4, 
            mt: 6,
            background: 'rgba(255,255,255,0.95)',
            backdropFilter: 'blur(10px)',
            borderRadius: 3,
            border: '1px solid rgba(255,255,255,0.2)'
          }}
        >
          <Typography 
            variant="h4" 
            sx={{ 
              fontWeight: 300,
              mb: 4,
              textAlign: 'center',
              color: '#2c3e50'
            }}
          >
            Casos de Uso
          </Typography>
          <Grid container spacing={4}>
            {[
              {
                title: "Desarrollo y Testing",
                description: "Ideal para desarrollar y probar aplicaciones containerizadas antes de desplegarlas en producción."
              },
              {
                title: "Aplicaciones Web",
                description: "Hosting de aplicaciones web con balanceamiento de carga automático y alta disponibilidad."
              },
              {
                title: "Microservicios",
                description: "Despliegue y gestión de arquitecturas de microservicios de manera eficiente."
              },
              {
                title: "IoT y Edge Computing",
                description: "Procesamiento de datos en el edge para aplicaciones de Internet of Things."
              }
            ].map((useCase, index) => (
              <Grid item xs={12} md={6} key={index}>
                <Box
                  sx={{
                    p: 3,
                    borderRadius: 2,
                    background: 'rgba(102, 126, 234, 0.1)',
                    border: '1px solid rgba(102, 126, 234, 0.2)',
                    height: '100%',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: '0 8px 25px rgba(102, 126, 234, 0.15)'
                    }
                  }}
                >
                  <Typography 
                    variant="h6" 
                    sx={{ 
                      fontWeight: 500,
                      mb: 2,
                      color: '#667eea'
                    }}
                  >
                    {useCase.title}
                  </Typography>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      color: '#34495e',
                      lineHeight: 1.6
                    }}
                  >
                    {useCase.description}
                  </Typography>
                </Box>
              </Grid>
            ))}
          </Grid>
        </Paper>

        {/* Video Section */}
        <Paper 
          elevation={0}
          sx={{ 
            p: 4, 
            mt: 6,
            background: 'rgba(255,255,255,0.95)',
            backdropFilter: 'blur(10px)',
            borderRadius: 3,
            border: '1px solid rgba(255,255,255,0.2)'
          }}
        >
          <Typography 
            variant="h4" 
            sx={{ 
              fontWeight: 300,
              mb: 4,
              textAlign: 'center',
              color: '#2c3e50'
            }}
          >
            Video Demostrativo
          </Typography>
          <Box 
            sx={{ 
              display: 'flex', 
              justifyContent: 'center',
              '& iframe': {
                borderRadius: 2,
                boxShadow: '0 8px 25px rgba(0,0,0,0.15)'
              }
            }}
          >
            <iframe
              width="100%"
              height="400"
              src="https://www.youtube.com/embed/6WthsF9rsC8?si=j7yfX21jN_zqMPtj"
              title="YouTube video player"
              frameBorder="0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
              referrerPolicy="strict-origin-when-cross-origin"
              allowFullScreen
              style={{ 
                maxWidth: '800px',
                borderRadius: '8px'
              }}
            />
          </Box>
        </Paper>
      </Container>
    </Box>
  );
};

export default Home;
